        consumed_changesets: agg.consumed,
        pre_state_update,
        pre_json_path: ws.config.pre_json_path(),
        pre_json_original_text,
        delete_pre_json,
        pre_cursor_updates: Vec::new(),
        observed_versions: base_versions,
        diagnostics,
    })
}

