        let Ok(operation) = self.prepared_operation(id) else {
            return std::time::Duration::ZERO;
        };
        checked_provider_for(operation).map_or(std::time::Duration::ZERO, |provider| {
            provider.confirmation_window(&ProviderRequest {
                id,
                operation,
                artifacts: None,
            })
        })
    }
}

