    let mut extra = Vec::new();
    for (name, member_changelog) in members {
        let Ok(section) = changelog_section(root, member_changelog, version)? else {
            continue;
        };
        for entry in entries(&section) {
            let Some(body) = entry.strip_prefix("- ") else {
